//! The IPC contract (ADR-0007): the commands the webview may call, registered
//! with tauri-specta so that the TypeScript bindings come from the Rust types.
//!
//! Every command also needs a permission (`build.rs`) and a grant
//! (`capabilities/`), or Tauri refuses it (ADR-0004).

#[cfg(feature = "validation")]
pub(crate) mod channel;

use std::fs;
use std::path::{Path, PathBuf};

use specta_typescript::Typescript;
use tauri::Wry;
use tauri_specta::{Builder, ErrorHandlingMode, collect_commands};

use crate::commands::{interface, startup};

/// The first line of every generated file.
const HEADER: &str =
    "// Generated by `task gen` from the Rust IPC types (ADR-0007). Do not edit or commit it.";

/// Why the bindings could not be written.
#[derive(Debug, thiserror::Error)]
pub enum BindingsError {
    /// The output folder could not be created.
    #[error("could not create the bindings folder {path}")]
    Directory {
        /// The folder.
        path: PathBuf,
        /// The cause.
        #[source]
        source: std::io::Error,
    },
    /// The TypeScript exporter failed.
    #[error("could not export the bindings to {path}")]
    Export {
        /// The file being written.
        path: PathBuf,
        /// The cause, boxed because the exporter's error is large.
        #[source]
        source: Box<specta_typescript::Error>,
    },
}

/// The commands of every build, followed by the extra commands given.
/// `collect_commands!` needs the paths as plain tokens, so they pass through
/// unparsed.
macro_rules! app_commands {
    ($($extra:tt)*) => {
        collect_commands![
            startup::get_startup_status,
            interface::get_interface_settings,
            interface::update_interface_settings,
            $($extra)*
        ]
    };
}

/// The commands of every build.
#[expect(
    trivial_casts,
    reason = "collect_commands! casts each command to a function pointer for specta"
)]
fn app_builder() -> Builder<Wry> {
    Builder::new()
        .error_handling(ErrorHandlingMode::Result)
        .commands(app_commands![])
}

/// The validation commands (V1, V2, V3).
#[cfg(feature = "validation")]
#[expect(
    trivial_casts,
    reason = "collect_commands! casts each command to a function pointer for specta"
)]
fn validation_builder() -> Builder<Wry> {
    Builder::new()
        .error_handling(ErrorHandlingMode::Result)
        .commands(collect_commands![
            crate::commands::validation::stream_validation_events,
            crate::commands::validation::validation_ungranted_command,
        ])
}

/// The commands the app answers: the app commands and, in validation builds,
/// the validation commands.
#[cfg_attr(
    feature = "validation",
    expect(
        trivial_casts,
        reason = "collect_commands! casts each command to a function pointer for specta"
    )
)]
pub(crate) fn runtime_builder() -> Builder<Wry> {
    #[cfg(not(feature = "validation"))]
    {
        app_builder()
    }
    #[cfg(feature = "validation")]
    {
        Builder::new()
            .error_handling(ErrorHandlingMode::Result)
            .commands(app_commands![
                crate::commands::validation::stream_validation_events,
                crate::commands::validation::validation_ungranted_command,
            ])
    }
}

/// Writes the TypeScript bindings into `directory`: `bindings.ts` with the app
/// commands and, in validation builds, `validation.ts` with the validation
/// commands. The folder is generated and never committed.
pub fn export_bindings(directory: &Path) -> Result<(), BindingsError> {
    fs::create_dir_all(directory).map_err(|source| BindingsError::Directory {
        path: directory.to_path_buf(),
        source,
    })?;
    export(&app_builder(), &directory.join("bindings.ts"))?;
    #[cfg(feature = "validation")]
    export(&validation_builder(), &directory.join("validation.ts"))?;
    Ok(())
}

fn export(builder: &Builder<Wry>, path: &Path) -> Result<(), BindingsError> {
    builder
        .export(Typescript::default().header(HEADER), path)
        .map_err(|source| BindingsError::Export {
            path: path.to_path_buf(),
            source: Box::new(source),
        })
}

/// The bindings folder in the source tree, which debug builds keep current.
#[cfg(debug_assertions)]
pub(crate) fn source_bindings_directory() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../src/lib/generated")
}
